import boto3

def run_ocr(bucket_name, document_key):
    textract_client = boto3.client('textract')
    response = textract_client.detect_document_text(
        Document={
            'S3Object': {
                'Bucket': bucket_name,
                'Name': document_key
            }
        }
    )
    return response

from typing import Any, Dict, List, Union


class StorageRequest:
    def __init__(self, bucket: str, key: str, metadata: Dict[str, Any] = None):
        self.bucket = bucket
        self.key = key
        self.metadata = metadata or {}


class StorageResponse:
    def __init__(self, status_code: int, headers: Dict[str, str], body: Union[str, bytes]):
        self.status_code = status_code
        self.headers = headers
        self.body = body


def normalize_metadata(metadata: Dict[str, Any]) -> Dict[str, str]:
    return {k: str(v) for k, v in metadata.items()}


def normalize_response(response: StorageResponse) -> Dict[str, Any]:
    return {
        'status_code': response.status_code,
        'headers': response.headers,
        'body': response.body.decode() if isinstance(response.body, bytes) else response.body
    }

import boto3

class StorageClient:
    def __init__(self, region_name, access_key, secret_key):
        self.s3_client = boto3.client(
            's3',
            region_name=region_name,
            aws_access_key_id=access_key,
            aws_secret_access_key=secret_key
        )

    def get_client(self):
        return self.s3_client

import boto3

def list_objects(bucket_name, prefix=''):
    s3 = boto3.client('s3')
    response = s3.list_objects_v2(Bucket=bucket_name, Prefix=prefix)
    if 'Contents' in response:
        return [obj['Key'] for obj in response['Contents']]
    else:
        return []

import boto3

def upload_to_s3(bucket_name, object_key, file_path):
    s3_client = boto3.client('s3')
    try:
        s3_client.upload_file(file_path, bucket_name, object_key)
        print(f'File uploaded successfully to {bucket_name}/{object_key}')
    except Exception as e:
        print(f'Error uploading file: {e}')

if __name__ == '__main__':
    upload_to_s3('my-bucket', 'my-object-key', 'path/to/my/file.txt')
